import{c as t,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"殿前欢·对菊自叹","description":"","frontmatter":{"title":"殿前欢·对菊自叹","author":"张养浩","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/11.md","filePath":"books/shici/yuanqu/11.md"}'),h={name:"books/shici/yuanqu/11.md"};function s(u,a,c,p,d,q){const o=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="殿前欢·对菊自叹" tabindex="-1">殿前欢·对菊自叹 <a class="header-anchor" href="#殿前欢·对菊自叹" aria-label="Permalink to &quot;殿前欢·对菊自叹&quot;">​</a></h1><p><strong>[元] <a href="/authors/zhangyanghao.html">张养浩</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>对菊自叹，可怜秋，一帘疏雨暗西楼。黄花庭院，青灯夜雨，白发秋风。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>殿前欢：曲牌名</li><li>对菊自叹：对着菊花独自感叹</li><li>可怜：可惜</li><li>一帘疏雨：稀疏的雨点像帘子一样</li><li>暗西楼：使西楼显得昏暗</li><li>黄花：菊花</li><li>青灯：油灯</li><li>夜雨：夜间的雨</li><li>白发：白发人，指作者自己</li><li>秋风：秋天的风</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>对着菊花独自感叹，可惜这秋天，稀疏的雨点像帘子一样使西楼显得昏暗。庭院里菊花盛开，青灯映照着夜雨，白发人面对着秋风。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是张养浩的代表作，通过对菊自叹，表达了作者对人生易老、时光流逝的感慨。</p><p>&quot;对菊自叹&quot;，开篇就点明了主题。菊花是秋天的象征，也是高洁品格的象征，作者对菊自叹，既有对时光流逝的感慨，也有对自身境遇的感叹。</p><p>&quot;可怜秋，一帘疏雨暗西楼&quot;，写秋天的景象。&quot;可怜&quot;二字，既是对秋天的惋惜，也是对自己人生的感叹。疏雨暗楼，营造出一种凄清的氛围。</p><p>&quot;黄花庭院，青灯夜雨，白发秋风&quot;，以三个意象作结。黄花庭院写秋景，青灯夜雨写孤寂，白发秋风写人生易老。三个意象叠加，将作者的感慨表现得淋漓尽致。</p><p>全曲语言凝练，意境凄清，将人生易老的感慨与秋日景色完美融合。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>张养浩</strong>（1270年－1329年），字希孟，号云庄，元代著名散曲家。其散曲多写隐逸生活，风格清新自然，也有关心民生疾苦之作。</p><p><a href="/authors/zhangyanghao.html">查看作者详情 →</a></p></blockquote>',17)),n(o)])}const b=t(h,[["render",s]]);export{m as __pageData,b as default};
